type WechatServiceHTTPClient interface {
	// AdoptWechatTemplate AdoptWechatTemplate takes one public-library template onto this app
	// through the app's current token. The same library template is not
	// adopted twice onto the same live app. This call does not invent a
	// template. Permission: wechat:dispatch:create.
	AdoptWechatTemplate(ctx context.Context, req *AdoptWechatTemplateRequest, opts ...http.CallOption) (rsp *AdoptedTemplate, err error)
	// CreateWechatApp CreateWechatApp connects a mini program, or an official account with
	// a Service Account or Subscription Account kind, by Direct Hold. The
	// response returns the generated Token and EncodingAESKey in full once.
	CreateWechatApp(ctx context.Context, req *CreateWechatAppRequest, opts ...http.CallOption) (rsp *WechatAppPushSecret, err error)
	// CreateWechatDispatch CreateWechatDispatch sends one adopted template to one openid and
	// waits until WeChat accepts or rejects. Acceptance and business
	// rejection each leave a new dispatch. Permission: wechat:dispatch:create.
	CreateWechatDispatch(ctx context.Context, req *CreateWechatDispatchRequest, opts ...http.CallOption) (rsp *WechatDispatch, err error)
	// CreateWechatPlatform CreateWechatPlatform registers a platform. The response carries masks,
	// never the secrets the operator just typed.
	CreateWechatPlatform(ctx context.Context, req *CreateWechatPlatformRequest, opts ...http.CallOption) (rsp *WechatPlatform, err error)
	// GetWechatApp GetWechatApp retrieves one app that is not withdrawn. The response
	// carries masks only.
	GetWechatApp(ctx context.Context, req *GetWechatAppRequest, opts ...http.CallOption) (rsp *WechatApp, err error)
	// GetWechatAppMenu GetWechatAppMenu returns the Custom Menu saved on one Service Account
	// and the last menu WeChat accepted. Neither is a secret. Permission:
	// wechat:app:list.
	GetWechatAppMenu(ctx context.Context, req *GetWechatAppMenuRequest, opts ...http.CallOption) (rsp *WechatAppMenu, err error)
	// GetWechatPlatform GetWechatPlatform retrieves one platform that is not withdrawn.
	GetWechatPlatform(ctx context.Context, req *GetWechatPlatformRequest, opts ...http.CallOption) (rsp *WechatPlatform, err error)
	// ListAdoptedTemplates ListAdoptedTemplates lists templates adopted onto this app from
	// WeChat's public library, including after the app is withdrawn.
	// Permission: wechat:dispatch:list.
	ListAdoptedTemplates(ctx context.Context, req *ListAdoptedTemplatesRequest, opts ...http.CallOption) (rsp *AdoptedTemplateSet, err error)
	// ListAuthorizationPlatforms ListAuthorizationPlatforms lists ready platforms an operator can
	// choose when starting a Platform Authorization. Withdrawn and unready
	// platforms are omitted. Masks and secrets are not returned. Permission:
	// wechat:app:create.
	ListAuthorizationPlatforms(ctx context.Context, req *ListAuthorizationPlatformsRequest, opts ...http.CallOption) (rsp *WechatAuthorizationPlatformSet, err error)
	// ListWechatApps ListWechatApps lists apps that are not withdrawn. Responses carry
	// masks only.
	ListWechatApps(ctx context.Context, req *ListWechatAppsRequest, opts ...http.CallOption) (rsp *WechatAppSet, err error)
	// ListWechatDispatches ListWechatDispatches lists send attempts for live and withdrawn apps.
	// app_id filters to one app. Permission: wechat:dispatch:list.
	ListWechatDispatches(ctx context.Context, req *ListWechatDispatchesRequest, opts ...http.CallOption) (rsp *WechatDispatchSet, err error)
	// ListWechatPlatforms ListWechatPlatforms lists platforms that are not withdrawn. Responses
	// carry masks only.
	ListWechatPlatforms(ctx context.Context, req *ListWechatPlatformsRequest, opts ...http.CallOption) (rsp *WechatPlatformSet, err error)
	// MiniProgramLogin MiniProgramLogin exchanges one mini program's one-time login code for
	// that WeChat App's openid and, when WeChat supplied one, its unionid.
	// Direct Hold and Platform Authorization share this entry; the caller
	// does not name the connection. No back-office Principal and no menu
	// permission are required. The response carries no session_key and no
	// system credential. The call creates no WeChat User, System User, or
	// Login Session, and it writes no Login Log.
	MiniProgramLogin(ctx context.Context, req *MiniProgramLoginRequest, opts ...http.CallOption) (rsp *MiniProgramIdentity, err error)
	// ProbeWechatApp ProbeWechatApp runs the WeChat Connectivity Test for one app. The
	// test uses the app's current token and creates no WeChat Dispatch. A
	// definitive refusal lapses the app. A timeout, a business rejection,
	// or an unready platform fails the test and leaves the app unlapsed.
	// A lapsed app is refused until it is restored. A suspended app can
	// still be tested. Permission: wechat:app:probe.
	ProbeWechatApp(ctx context.Context, req *ProbeWechatAppRequest, opts ...http.CallOption) (rsp *ProbeWechatAppResult, err error)
	// ProbeWechatPlatform ProbeWechatPlatform runs the WeChat Connectivity Test for one platform.
	// A platform that is missing a secret or a verify ticket fails the test.
	// Success and failure change no WeChat App. Permission: wechat:platform:probe.
	ProbeWechatPlatform(ctx context.Context, req *ProbeWechatPlatformRequest, opts ...http.CallOption) (rsp *ProbeWechatPlatformResult, err error)
	// PublishWechatAppMenu PublishWechatAppMenu sends the whole saved menu and replaces that
	// Service Account's default menu at WeChat. A business refusal or a
	// timeout leaves the previously accepted menu in place and does not
	// lapse the app. A definitive refusal lapses the app and still leaves
	// that menu. Permission: wechat:app:update.
	PublishWechatAppMenu(ctx context.Context, req *PublishWechatAppMenuRequest, opts ...http.CallOption) (rsp *WechatAppMenu, err error)
	// RegenerateWechatAppPushSecret RegenerateWechatAppPushSecret replaces the Push Secret. The response
	// returns the new pair in full once. The previous pair is invalidated
	// immediately. The app is not withdrawn and its suspension is unchanged.
	RegenerateWechatAppPushSecret(ctx context.Context, req *RegenerateWechatAppPushSecretRequest, opts ...http.CallOption) (rsp *WechatAppPushSecret, err error)
	// SaveWechatAppMenu SaveWechatAppMenu stores the Custom Menu in this system and does not
	// call WeChat. The last menu WeChat accepted stays as it was.
	// Permission: wechat:app:update.
	SaveWechatAppMenu(ctx context.Context, req *SaveWechatAppMenuRequest, opts ...http.CallOption) (rsp *WechatAppMenu, err error)
	// SetWechatAppSuspended SetWechatAppSuspended suspends or resumes the app. The app stays on
	// the live list either way.
	SetWechatAppSuspended(ctx context.Context, req *SetWechatAppSuspendedRequest, opts ...http.CallOption) (rsp *WechatApp, err error)
	// StartWechatAuthorization StartWechatAuthorization returns the link the other administrator
	// opens. The chosen platform must be ready and not withdrawn. No WeChat
	// App is created by this call. Permission: wechat:app:create.
	StartWechatAuthorization(ctx context.Context, req *StartWechatAuthorizationRequest, opts ...http.CallOption) (rsp *WechatAuthorization, err error)
	// UpdateWechatApp UpdateWechatApp corrects the display name and, when app_secret is
	// non-blank, replaces the AppSecret. The response carries masks only
	// and never the submitted secret. A wx_app_id that differs from the
	// stored value is refused.
	UpdateWechatApp(ctx context.Context, req *UpdateWechatAppRequest, opts ...http.CallOption) (rsp *WechatApp, err error)
	// UpdateWechatPlatform UpdateWechatPlatform corrects the display name and, when a secret is
	// non-blank, replaces that secret. A component AppID that differs from
	// the stored value is refused. Blank secrets keep their stored values.
	UpdateWechatPlatform(ctx context.Context, req *UpdateWechatPlatformRequest, opts ...http.CallOption) (rsp *WechatPlatform, err error)
	// WithdrawWechatApp WithdrawWechatApp soft-deletes the app. The row leaves the live list;
	// it is not hard-deleted. The same AppID can be connected again as a
	// new row.
	WithdrawWechatApp(ctx context.Context, req *WithdrawWechatAppRequest, opts ...http.CallOption) (rsp *emptypb.Empty, err error)
	// WithdrawWechatPlatform WithdrawWechatPlatform soft-deletes the platform. The row leaves the
	// live list; it is not hard-deleted.
	WithdrawWechatPlatform(ctx context.Context, req *WithdrawWechatPlatformRequest, opts ...http.CallOption) (rsp *emptypb.Empty, err error)
}

